INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(125806, 'ruRU', '', 'После того как вас уничтожат, если захотите заполнить небольшой опрос, это поможет нам лучше обслуживать вас в будущем.', 24330),
(125807, 'ruRU', '', 'Попробуй добавить немного светлой магии. Обычно это помогает.', 24330),
(125809, 'ruRU', '', 'Мутировавшую спору можно найти на вершине этого утёса. Тебе придётся прорубаться туда с боем, удачи!', 24330),
(125811, 'ruRU', '', 'Взлетай с нами. Лети быстро и прямо!', 24330),
(125815, 'ruRU', '', 'Портал готов. Я с тобой, $p!', 24330),
(125816, 'ruRU', '', 'Круул возродится!', 24330),
(125817, 'ruRU', '', 'Твои прославленные силы природы не выстоят против скверны!', 24330),
(125818, 'ruRU', '', 'Берегись! Ещё прибывают!', 24330),
(125819, 'ruRU', '', 'Почти добрались! Так держать!', 24330),
(125821, 'ruRU', '', 'Приливный камень будет нашим!', 24330),
(125822, 'ruRU', '', 'Может, мы переборщили... Нам будет паршиво, когда это пройдёт! Зато закрыть порталы теперь будет проще простого!', 24330),
(125823, 'ruRU', '', 'Ты видишь пивовара?', 24330),
(125829, 'ruRU', '', 'Я всегда хотел изучать Прядение туманов! Прощай, Пивовар.', 24330),
(125830, 'ruRU', '', 'Пивовар? Ты пытался убить нас!', 24330),
(125831, 'ruRU', '', 'Я пришла предупредить вас так быстро, как могла. Я опоздала...', 24330),
(125833, 'ruRU', '', 'Я... я принесла сюда отравленное пиво. Если бы я только проверила его сначала...', 24330),
(125835, 'ruRU', '', 'Стой! Кто приближается к Хранилищу Эйир?', 24330),
(125840, 'ruRU', '', 'Матрица Автоматического Деспотичного Ассистирования и Манипулирования - М/А/Д/А/М - запущена. Приветствую, пользователь.', 24330),
(125841, 'ruRU', '', 'Обнаружен сбой питания... запуск восстановления системы...', 24330),
(125843, 'ruRU', '', 'Доступ разрешён. Приветствую, лорд Мефистрот. Чем я могу служить вам сегодня?', 24330),
(125870, 'ruRU', '', 'Разумеется, лорд Мефистрот. Один момент, я получаю доступ к вашим предыдущим настройкам пользователя...', 24330),
(125871, 'ruRU', '', 'Моя стандартная программа была изменена, чтобы более полно удовлетворять все потребности лорда Мефистрота.', 24330),
(125872, 'ruRU', '', 'По вашему запросу я теперь предлагаю ряд услуг за пределами моей обычной программы, чтобы лучше служить своему тёмному повелителю.', 24330),
(125875, 'ruRU', '', 'У меня есть сферы, которые могут оказаться особенно полезны в твоих начинаниях, архимаг, если они тебе понадобятся.', 24330),
(125876, 'ruRU', '', 'У меня есть свежая еда и бинты для тебя, архимаг, если они тебе нужны.', 24330),
(125879, 'ruRU', '', 'Прошу прощения за беспорядок. Ярл думал, что один из его питомцев сможет меня замедлить.', 24330),
(125880, 'ruRU', '', 'Идём, понесём бой к нему!', 24330),
(125881, 'ruRU', '', 'Позволь нам направить тебя к нежизни!', 24330),
(125883, 'ruRU', '', 'Если ты думаешь, что можешь бросить мои кости тут замерзать, то здорово ошибаешься. Ха-ха, идём!', 24330),
(125886, 'ruRU', '', 'Конечно, мой повелитель. Вы - Мефистрот, сильнейший и мудрейший из всех натрезимов.', 24330),
(125887, 'ruRU', '', 'Бог Скверны и Пламени, сам Саргерас, избрал вас, чтобы вести натрезимов к славе после унизительного поражения Тихондриуса от руки Иллидана Штормграйва.', 24330),
(125893, 'ruRU', '', 'Аааааааа!', 24330),
(125897, 'ruRU', '', 'Как вы знаете, лорд Мефистрот, этот корабль оснащён рядом защитных систем, разработанных для предотвращения различных катастрофических сбоев.', 24330),
(125899, 'ruRU', '', 'Доставит ли удовольствие моему тёмному повелителю, если я отключу все аварийные и защитные системы корабля?', 24330),
(125900, 'ruRU', '', 'Мы... никогда... не... склонимся!', 24330),
(125906, 'ruRU', '', 'Конечно. Всё для вас, лорд Мефистрот, ваше удовольствие - мой приказ.', 24330),
(125907, 'ruRU', '', 'Один момент, я отключаю защитные системы...', 24330),
(125911, 'ruRU', '', 'Переопределение завершено. Если это угодно моему господину, я взяла на себя смелость разблокировать машинное отделение.', 24330),
(125913, 'ruRU', '', 'Если вы хотите уничтожить корабль, перегрузка генераторов вызовет катастрофическое повреждение двигателей.', 24330),
(125914, 'ruRU', '', 'Будьте осторожны, господин!', 24330);
